const lucide = (name: string, ...d: string[]): BrandMarkDefinition => ({
  name,
  viewBox: '0 0 24 24',
  shapes: d.map((path) => ({ fill: 'none', stroke: 'currentColor', strokeWidth: 2, d: path })),
});

